constexpr s32 kFirstPrivate2 = 64; // s32: first stream id 0xBF present, else 0
constexpr s32 kFirstAudio = 68;    // s32: first stream id 0xC0..0xDF present, else 0
constexpr s32 kFirstVideo = 72;    // s32: first stream id 0xE0..0xEF present, else 0
constexpr s32 kAudio = 76;         // s32[4]: the first audio stream's entry bytes +25, +26, +27 and word +28
constexpr s32 kVideo = 92;         // s32[13]: the first video stream's entry (sub_58B978)
